import Link from"next/link";import{loginAction}from"@/app/actions";import{getMessages}from"@/lib/i18n-server";export default async function Login(){const m=await getMessages();return <section className="auth"><form action={loginAction} className="panel"><span className="eyebrow">{m.welcome}</span><h1>{m.loginTitle}</h1><label>Email<input name="email" type="email" required autoComplete="email"/></label><label>{m.password}<input name="password" type="password" required autoComplete="current-password"/></label><button>{m.login}</button><p>{m.noAccount} <Link href="/register">{m.create}</Link></p></form></section>}